out[\"correlations\"]={}
vs=list(out[\"diagnostics\"])
for i,a in enumerate(vs):
 for b in vs[i+1:]:
  d=x[(x.recall_post==1)&x[a].isin(range(1,6))&x[b].isin(range(1,6))];w=d.weight_base;av=mean(d,a);bv=mean(d,b)
  out[\"correlations\"][a+\"__\"+b]=dict(**base(d),r=round(np.sum(w*(d[a]-av)*(d[b]-bv))/math.sqrt(np.sum(w*(d[a]-av)**2)*np.sum(w*(d[b]-bv)**2)),4))
out[\"children_stress\"]={str(h):dist(x[x.children_under18==h],\"meal_stress_pre\",[1,2,3,4,5]) for h in [0,1]}
out[\"user_experience\"]={v:dist(x[(x.followup_status==1)&(x.usage_post==1)],v,valid) for v,valid in [(\"usage_days_post\",list(range(8))),(\"satisfaction_post\",list(range(1,6)))]}
out[\"older_exploratory_bases\"]={k:{str(z):base(p[(p.assignment==z)&(p.age_band==4)&(p.online_grocery_pre==1)&p.digital_confidence_pre.isin([4,5])]) for z in [0,1]} for k,p in pairs.items()}
